function Layout({children}){const[o,setO]=useState(false),{pathname}=useLocation();useEffect(()=>{setO(false);scrollTo(0,0);document.title='Prism Edu | '+(pathname==='/'?'School Business & Growth':pathname.slice(1).replaceAll('-',' '))},[pathname]);return <><LeadershipAwardPopup/><AnnouncementBar/><header className="sticky top-0 z-50 border-b bg-white/95 backdrop-blur"><div className="wrap flex h-[74px] items-center justify-between gap-2 xl:gap-3"><Logo/><nav className="hidden items-center xl:flex">{nav.map(([l,t])=><NavLink key={l} end={t==='/'} to={t} className={({isActive})=>'nav-link relative whitespace-nowrap px-2 py-3 text-[11px] font-semibold tracking-[.01em] transition-colors duration-200 '+(isActive?'is-active text-gold':'text-ink hover:text-gold')}>{l}</NavLink>)}</nav><div className="ml-auto flex items-center gap-1"><div className="hidden items-center gap-0.5 xl:flex"><UtilityLink to="/admin" label="Admin Panel"><ShieldCheck size={18}/></UtilityLink><UtilityLink to="/account" label="Login / Register"><Users size={18}/></UtilityLink></div><div className="hidden xl:block"><Link className="btn ml-2 !px-3 !py-2.5 text-xs" to="/business-meeting">Meeting <ArrowRight size={15}/></Link></div><UtilityLink to="/account" label="Login / Register"><span className="xl:hidden"><Users size={18}/></span><span className="hidden xl:block"/></UtilityLink><button type="button" className="grid h-9 w-9 place-items-center rounded-lg border border-slate-200 text-ink xl:hidden" onClick={()=>setO(!o)} aria-expanded={o} aria-controls="mobile-navigation" aria-label={o?'Close navigation':'Open navigation'}>{o?<X size={21}/>:<Menu size={21}/>}</button></div></div><div className="bus-road" aria-hidden="true"><Bus className="school-bus" size={20}/></div>{o&&<nav id="mobile-navigation" className="border-t bg-white px-5 pb-5 xl:hidden">{nav.map(([l,t])=><NavLink key={l} end={t==='/'} className={({isActive})=>'block border-b py-3 text-sm font-bold transition '+(isActive?'text-gold':'text-ink hover:text-gold')} to={t}>{l}</NavLink>)}<Link className="flex items-center gap-3 border-b py-3 text-sm font-bold text-ink" to="/admin"><ShieldCheck size={18}/>Admin Panel</Link><Link className="flex items-center gap-3 border-b py-3 text-sm font-bold text-ink" to="/account"><Users size={18}/>Login / Register</Link><Link className="btn mt-4 w-full" to="/business-meeting">Meeting <ArrowRight size={16}/></Link></nav>}</header><main>{children}{!['/','/about','/services','/events-awards'].includes(pathname)&&<div className="page-brand-accent"><img src={PRISM_LOGO_URL} alt="Prism Edu Consultancy" width="112" height="112" loading="lazy"/><p>Prism Edu Consultancy</p></div>}</main><GlobalFooter/></>}
