function HomepageHero(){
  const[index,setIndex]=useState(0),[hovered,setHovered]=useState(false),[touchStart,setTouchStart]=useState(null);
  useEffect(()=>{if(hovered)return;const timer=setTimeout(()=>setIndex(i=>(i+1)%heroSlides.length),6000);return()=>clearTimeout(timer)},[index,hovered]);
  const move=step=>setIndex(i=>(i+step+heroSlides.length)%heroSlides.length);
  return <section className="relative overflow-hidden bg-slate-100" aria-roledescription="carousel" aria-label="Prism Edu services" onMouseEnter={()=>setHovered(true)} onMouseLeave={()=>setHovered(false)} onTouchStart={e=>setTouchStart(e.touches[0].clientX)} onTouchEnd={e=>{if(touchStart===null)return;const distance=e.changedTouches[0].clientX-touchStart;if(Math.abs(distance)>45)move(distance<0?1:-1);setTouchStart(null)}}>
    <div className="relative mx-auto aspect-[1600/349] w-full max-w-[1600px] overflow-hidden bg-white shadow-sm">
      {heroSlides.map((slide,i)=><img key={slide.image} src={slide.image} alt={slide.alt} width="1600" height="349" loading={i===0?'eager':'lazy'} fetchPriority={i===0?'high':'auto'} className={'absolute inset-0 h-full w-full object-contain transition-opacity duration-700 ease-in-out '+(i===index?'z-10 opacity-100':'z-0 opacity-0')} aria-hidden={i!==index}/>) }
    </div>
    <button type="button" onClick={()=>move(-1)} className="absolute left-3 top-1/2 z-20 hidden h-11 w-11 -translate-y-1/2 place-items-center rounded-full border border-white bg-white/80 text-ink shadow-md backdrop-blur transition hover:bg-white md:grid" aria-label="Previous hero slide"><ChevronLeft size={20}/></button><button type="button" onClick={()=>move(1)} className="absolute right-3 top-1/2 z-20 hidden h-11 w-11 -translate-y-1/2 place-items-center rounded-full border border-white bg-white/80 text-ink shadow-md backdrop-blur transition hover:bg-white md:grid" aria-label="Next hero slide"><ChevronRight size={20}/></button>
    <div className="absolute bottom-2 left-1/2 z-20 flex -translate-x-1/2 gap-2 rounded-full bg-white/75 px-3 py-2 shadow-sm backdrop-blur">{heroSlides.map((item,i)=><button key={item.type} onClick={()=>setIndex(i)} className={'h-2.5 rounded-full transition-all '+(i===index?'w-8 bg-gold':'w-2.5 bg-slate-300 hover:bg-slate-400')} aria-label={'Show '+item.alt} aria-current={i===index?'true':undefined}/>)}</div>
  </section>
}

