function Form({title='Tell us about your requirement',fields=[]}){const[ok,setOk]=useState(false);if(ok)return <div className="card text-center"><CheckCircle2 className="mx-auto mb-3 text-green-600" size={42}/><h3>Thank you for your enquiry</h3><p className="mt-2 text-sm">Connect a form backend before publishing to receive submissions.</p></div>;return <form className="card" onSubmit={e=>{e.preventDefault();setOk(true)}}><h3 className="mb-6 text-xl">{title}</h3><div className="grid gap-4 md:grid-cols-2">{['Name','Phone number','Email address','City / Location',...fields].map((x,i)=>x.includes('Message')||x.includes('Challenges')?<textarea key={x} required className="field md:col-span-2" rows="4" placeholder={x}/>:<input key={x} required className="field" type={i===1?'tel':i===2?'email':'text'} placeholder={x}/>)}</div><label className="mt-4 flex gap-2 text-xs"><input type="checkbox" required/>I agree to be contacted about this enquiry.</label><button className="btn mt-5 w-full">Submit enquiry</button></form>}
