function WebsiteQuotationPage(){const[ok,setOk]=useState(false);if(ok)return <section className="wrap py-20"><div className="card mx-auto max-w-2xl text-center"><CheckCircle2 className="mx-auto text-emerald-600" size={44}/><h1 className="mt-4 text-3xl">Quotation request received</h1><p className="mt-3">Connect the existing enquiry backend before publishing to receive submissions.</p></div></section>;return <section className="bg-gradient-to-br from-blue-50 to-cream py-16 md:py-24"><div className="wrap"><Head label="DIGITAL SERVICES" title="Get Website Quotation" text="Tell us what your school or organization needs. No pricing or delivery commitment is generated automatically."/><form className="card mx-auto max-w-4xl" onSubmit={e=>{e.preventDefault();setOk(true)}}><div className="grid gap-4 md:grid-cols-2"><input required className="field" placeholder="School / Organization Name"/><input required className="field" placeholder="Contact Person"/><input required className="field" type="tel" placeholder="Phone"/><input required className="field" type="email" placeholder="Email"/><input className="field" type="url" placeholder="Existing Website URL (optional)"/><select required className="field" defaultValue=""><option value="" disabled>Required Service</option>{['New Website','Website Redesign','Website Management','Mobile App','Digital Marketing','School Automation','Complete Digital Package'].map(x=><option key={x}>{x}</option>)}</select><input required className="field md:col-span-2" placeholder="Number of pages / features required"/><textarea required className="field md:col-span-2" rows="5" placeholder="Brief requirement"/><select required className="field" defaultValue=""><option value="" disabled>Preferred contact method</option><option>Phone</option><option>Email</option><option>WhatsApp</option></select></div><label className="mt-4 flex gap-2 text-xs"><input type="checkbox" required/>I agree to be contacted about this quotation request.</label><button className="btn mt-6">Submit Quotation Request</button></form></div></section>}

