  <section className="relative isolate overflow-hidden bg-gradient-to-br from-[#eaf3fb] via-white to-[#faf4e8] py-16 md:py-24"><div className="absolute -right-24 -top-20 -z-10 h-80 w-80 rounded-full bg-blue-200/30 blur-3xl"/><div className="wrap"><span className="eyebrow">CONTACT PRISM EDU</span><h1 className="max-w-4xl text-4xl font-extrabold leading-tight text-ink md:text-6xl">Let’s Build Better Schools Together</h1><p className="mt-5 max-w-3xl text-lg leading-8">Connect with Prism Edu Consultancy for school setup, licensing, academic development, branding, admissions, restructuring, digital solutions and complete school growth support.</p><div className="mt-8 flex flex-col gap-3 sm:flex-row"><ConsultationLink/><button className="btn2" onClick={()=>document.getElementById('contact-form')?.scrollIntoView({behavior:'smooth'})}>Send an Enquiry <ArrowRight size={16}/></button></div></div></section>
